import java.time.Period;

public class Main {
    public static void main(String[] args) {
        LocalDate fechaNacimiento = LocalDate.of(1994, 6, 15);

        Period edad = Period.between(fechaNacimiento, LocalDate.now());
        System.out.println("Age: " + edad.getYears() + " years, " + edad.getMonths() + " months, " + edad.getDays() + " days");
    }
}

