import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

public class Main {
    public static void main(String[] args) {
        LocalDate hoy = LocalDate.now();
        LocalDate navidad = LocalDate.of(2025, 12, 25);
        long diasRestantes = ChronoUnit.DAYS.between(hoy, navidad);
        System.out.println("Today: " + hoy);
        System.out.println("Christmas: " + navidad);
        if (diasRestantes > 0) {
            System.out.println("There are " + diasRestantes + " days left until Christmas");
        } else if (diasRestantes == 0) {
            System.out.println("Today is Christmas!");
        } else {
            System.out.println("Christmas already passed " + Math.abs(diasRestantes) + " days ago");
        }
    }
}

